mkuse!{use crate :: mem :: MaybeUninit ;}
mkuse!{use crate :: { cmp , ptr } ;}

macro_rules! merge_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function merge in module {}", module_path!());
    };
}

mkfn!{
    merge_introspect!();
    # [doc = " Merges non-decreasing runs `v[..mid]` and `v[mid..]` using `scratch` as"] # [doc = " temporary storage, and stores the result into `v[..]`."] pub fn merge < T , F : FnMut (& T , & T) -> bool > (v : & mut [T] , scratch : & mut [MaybeUninit < T >] , mid : usize , is_less : & mut F ,) { let len = v . len () ; if mid == 0 || mid >= len || scratch . len () < cmp :: min (mid , len - mid) { return ; } unsafe { let buf = MaybeUninit :: slice_as_mut_ptr (scratch) ; let v_base = v . as_mut_ptr () ; let v_mid = v_base . add (mid) ; let v_end = v_base . add (len) ; let left_len = mid ; let right_len = len - mid ; let left_is_shorter = left_len <= right_len ; let save_base = if left_is_shorter { v_base } else { v_mid } ; let save_len = if left_is_shorter { left_len } else { right_len } ; ptr :: copy_nonoverlapping (save_base , buf , save_len) ; let mut merge_state = MergeState { start : buf , end : buf . add (save_len) , dst : save_base } ; if left_is_shorter { merge_state . merge_up (v_mid , v_end , is_less) ; } else { merge_state . merge_down (v_base , buf , v_end , is_less) ; } } }
}
mkitem!{mkstruct!{struct MergeState < T > { start : * mut T , end : * mut T , dst : * mut T , }}}
mkitem!{mkimpl!{impl < T > MergeState < T > { # [doc = " # Safety"] # [doc = " The caller MUST guarantee that `self` is initialized in a way where `start -> end` is"] # [doc = " the longer sub-slice and so that `dst` can be written to at least the shorter sub-slice"] # [doc = " length times. In addition `start -> end` and `right -> right_end` MUST be valid to be"] # [doc = " read. This function MUST only be called once."] unsafe fn merge_up < F : FnMut (& T , & T) -> bool > (& mut self , mut right : * const T , right_end : * const T , is_less : & mut F ,) { unsafe { let left = & mut self . start ; let out = & mut self . dst ; while * left != self . end && right as * const T != right_end { let consume_left = ! is_less (& * right , & * * left) ; let src = if consume_left { * left } else { right } ; ptr :: copy_nonoverlapping (src , * out , 1) ; * left = left . add (consume_left as usize) ; right = right . add (! consume_left as usize) ; * out = out . add (1) ; } } } # [doc = " # Safety"] # [doc = " The caller MUST guarantee that `self` is initialized in a way where `left_end <- dst` is"] # [doc = " the shorter sub-slice and so that `out` can be written to at least the shorter sub-slice"] # [doc = " length times. In addition `left_end <- dst` and `right_end <- end` MUST be valid to be"] # [doc = " read. This function MUST only be called once."] unsafe fn merge_down < F : FnMut (& T , & T) -> bool > (& mut self , left_end : * const T , right_end : * const T , mut out : * mut T , is_less : & mut F ,) { unsafe { loop { let left = self . dst . sub (1) ; let right = self . end . sub (1) ; out = out . sub (1) ; let consume_left = is_less (& * right , & * left) ; let src = if consume_left { left } else { right } ; ptr :: copy_nonoverlapping (src , out , 1) ; self . dst = left . add (! consume_left as usize) ; self . end = right . add (consume_left as usize) ; if self . dst as * const T == left_end || self . end as * const T == right_end { break ; } } } } }}}
mkitem!{mkimpl!{impl < T > Drop for MergeState < T > { fn drop (& mut self) { unsafe { let len = self . end . offset_from_unsigned (self . start) ; ptr :: copy_nonoverlapping (self . start , self . dst , len) ; } } }}}